     1	/**
     2	 * @module core/config/timeouts
     3	 *
     4	 * Every deadline for calls that leave our process, in one place.
     5	 * Rule (CLAUDE.md): every external call has a timeout — no exceptions.
     6	 */
     7	
     8	/** Per-request timeout for external HTTP APIs (Open-Meteo, FEMA). */
     9	export const EXTERNAL_HTTP_TIMEOUT_MS = 30_000;
    10	
    11	/** Per-request timeout for Supabase (PostgREST) calls. */
    12	export const DATABASE_TIMEOUT_MS = 15_000;
    13	
    14	/**
    15	 * The answering model (OpenRouter, via the AI SDK).
    16	 * - `attemptMs`: one model attempt (all its steps). A turn has up to 2 attempts (validation retry).
    17	 * - `stepMs`: one model step. `toolMs`: one tool call.
    18	 * - `turnMs`: the whole turn, across both attempts. Kept well under the chat route's
    19	 *   `maxDuration`, which also has to cover the guard, database reads and saving the turn.
    20	 */
    21	export const AGENT_TIMEOUTS = { attemptMs: 60_000, stepMs: 25_000, toolMs: 10_000, turnMs: 100_000 } as const;
    22	
    23	/** The out-of-scope guard (Jev). After this the message is let through (fail open, D118). */
    24	export const GUARD_TIMEOUT_MS = 2_000;
    25	
    26	/** One judge call in the evals. */
    27	export const JUDGE_TIMEOUT_MS = 45_000;
=== src/core/data/http.ts
     1	/**
     2	 * @module core/data/http
     3	 *
     4	 * Shared `fetch` wrapper for external APIs: per-request timeout, retries on
     5	 * rate limits (429), server errors (5xx) and network failures, and errors in
     6	 * the unified boundary format.
     7	 */
     8	import { EXTERNAL_HTTP_TIMEOUT_MS } from "../config/timeouts";
     9	import { BoundaryError, describeUnknownError, type Boundary } from "../errors/boundaryError";
    10	
    11	/** A `fetch`-compatible function (injectable for tests). */
    12	export type FetchLike = (input: string, init?: RequestInit) => Promise<Response>;
    13	
    14	/** Waits for the given milliseconds (injectable for tests). */
    15	export type SleepFn = (ms: number) => Promise<void>;
    16	
    17	/** Default sleep using a timer. */
    18	export const sleep: SleepFn = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
    19	
    20	/** Options for {@link fetchJsonWithRetry}. */
    21	export interface FetchJsonOptions {
    22	  url: string;
    23	  boundary: Boundary;
    24	  functionName: string;
    25	  /** Error name used when every attempt fails, e.g. `OpenMeteoFetchError`. */
    26	  errorName: string;
    27	  fetchImpl?: FetchLike;
    28	  sleepImpl?: SleepFn;
    29	  /** Wait before each retry (its length = number of retries). */
    30	  backoffMs?: number[];
    31	  timeoutMs?: number;
    32	}
    33	
    34	/**
    35	 * Wraps a `fetch` so every request gets a deadline. If the caller passed its own
    36	 * abort signal, the request stops at whichever fires first. Used for libraries
    37	 * that call `fetch` themselves (e.g. supabase-js) and have no timeout option.
    38	 * @param baseFetch - the fetch to wrap.
    39	 * @param timeoutMs - deadline per request.
    40	 * @returns a fetch with the deadline applied.
    41	 */
    42	export function withTimeout(baseFetch: typeof fetch, timeoutMs: number): typeof fetch {
    43	  return (input, init) => {
    44	    const deadline = AbortSignal.timeout(timeoutMs);
    45	    const signal = init?.signal ? AbortSignal.any([init.signal, deadline]) : deadline;
    46	    return baseFetch(input, { ...init, signal });
    47	  };
    48	}
    49	
    50	/** True for responses worth retrying. */
    51	function isRetryableStatus(status: number): boolean {
    52	  return status === 429 || status >= 500;
    53	}
    54	
    55	/**
    56	 * Fetches JSON with timeout and retries.
    57	 * @param options - URL, error labels and injectable fetch/sleep.
    58	 * @returns the parsed JSON body (unvalidated — callers validate with Zod).
    59	 * @throws BoundaryError after the last failed attempt or on a non-retryable HTTP error.
    60	 */
    61	export async function fetchJsonWithRetry(options: FetchJsonOptions): Promise<unknown> {
    62	  const fetchImpl = options.fetchImpl ?? fetch;
    63	  const sleepImpl = options.sleepImpl ?? sleep;
    64	  const backoff = options.backoffMs ?? [2_000, 10_000, 30_000];
    65	  let lastProblem = "unknown error";
    66	
    67	  for (let attempt = 0; attempt <= backoff.length; attempt++) {
    68	    try {
    69	      const response = await fetchImpl(options.url, {
    70	        signal: AbortSignal.timeout(options.timeoutMs ?? EXTERNAL_HTTP_TIMEOUT_MS),
    71	      });
    72	      if (response.ok) return await response.json();
    73	
    74	      const body = (await response.text()).slice(0, 300);
    75	      lastProblem = `HTTP ${response.status}: ${body}`;
    76	      if (!isRetryableStatus(response.status)) break;
    77	
    78	      const retryAfterSeconds = Number(response.headers.get("retry-after"));
    79	      if (attempt < backoff.length) {
    80	        await sleepImpl(retryAfterSeconds > 0 ? retryAfterSeconds * 1_000 : backoff[attempt]);
    81	      }
    82	    } catch (error) {
    83	      lastProblem = `network error: ${describeUnknownError(error)}`;
    84	      if (attempt < backoff.length) await sleepImpl(backoff[attempt]);
    85	    }
    86	  }
    87	
    88	  throw new BoundaryError({
    89	    name: options.errorName,
    90	    message: `Request failed (${lastProblem})`,
    91	    functionName: options.functionName,
    92	    boundary: options.boundary,
    93	  });
    94	}
