     1	import { describe, expect, it, vi } from "vitest";
     2	import { fetchJsonWithRetry, withTimeout, type FetchLike } from "./http";
     3	
     4	/** A fetch that never answers, but stops when its signal aborts (like real fetch). */
     5	const hangingFetch = ((_input: unknown, init?: RequestInit) =>
     6	  new Promise((_resolve, reject) => {
     7	    init?.signal?.addEventListener("abort", () => reject(init.signal!.reason));
     8	  })) as typeof fetch;
     9	
    10	describe("withTimeout", () => {
    11	  it("aborts a request that takes longer than the deadline", async () => {
    12	    await expect(withTimeout(hangingFetch, 20)("https://x.test")).rejects.toMatchObject({ name: "TimeoutError" });
    13	  });
    14	
    15	  it("still honors the caller's own abort signal", async () => {
    16	    const controller = new AbortController();
    17	    const request = withTimeout(hangingFetch, 60_000)("https://x.test", { signal: controller.signal });
    18	    controller.abort(new Error("caller cancelled"));
    19	    await expect(request).rejects.toThrow("caller cancelled");
    20	  });
    21	
    22	  it("passes the response through when fast enough", async () => {
    23	    const fast = (async () => new Response("ok")) as unknown as typeof fetch;
    24	    await expect((await withTimeout(fast, 1_000)("https://x.test")).text()).resolves.toBe("ok");
    25	  });
    26	});
    27	
    28	const noSleep = vi.fn(async () => {});
    29	
    30	function respond(status: number, body: unknown): Response {
    31	  return new Response(typeof body === "string" ? body : JSON.stringify(body), { status });
    32	}
    33	
    34	describe("fetchJsonWithRetry", () => {
    35	  const base = { url: "https://x.test", boundary: "openMeteo" as const, functionName: "f", errorName: "TestError" };
    36	
    37	  it("returns JSON on success", async () => {
    38	    const fetchImpl: FetchLike = vi.fn(async () => respond(200, { ok: 1 }));
    39	    await expect(fetchJsonWithRetry({ ...base, fetchImpl, sleepImpl: noSleep })).resolves.toEqual({ ok: 1 });
    40	  });
    41	
    42	  it("retries 429 then succeeds", async () => {
    43	    const fetchImpl = vi
    44	      .fn<FetchLike>()
    45	      .mockResolvedValueOnce(respond(429, "slow down"))
    46	      .mockResolvedValueOnce(respond(200, { ok: 2 }));
    47	    await expect(fetchJsonWithRetry({ ...base, fetchImpl, sleepImpl: noSleep, backoffMs: [1] })).resolves.toEqual({
    48	      ok: 2,
    49	    });
    50	    expect(fetchImpl).toHaveBeenCalledTimes(2);
    51	  });
    52	
    53	  it("does not retry a 400 and throws in the unified format", async () => {
    54	    const fetchImpl = vi.fn<FetchLike>(async () => respond(400, "bad request"));
    55	    await expect(fetchJsonWithRetry({ ...base, fetchImpl, sleepImpl: noSleep, backoffMs: [1, 1] })).rejects.toThrow(
    56	      "TestError || Request failed (HTTP 400: bad request) || f || 🐸",
    57	    );
    58	    expect(fetchImpl).toHaveBeenCalledTimes(1);
    59	  });
    60	
    61	  it("gives up after all retries on network errors", async () => {
    62	    const fetchImpl = vi.fn<FetchLike>(async () => {
    63	      throw new Error("ECONNRESET");
    64	    });
    65	    await expect(fetchJsonWithRetry({ ...base, fetchImpl, sleepImpl: noSleep, backoffMs: [1, 1] })).rejects.toThrow(
    66	      /network error: ECONNRESET/,
    67	    );
    68	    expect(fetchImpl).toHaveBeenCalledTimes(3);
    69	  });
    70	});
