84	     1	/**
85	     2	 * @module core/ingest/planWeatherRange
86	     3	 *
87	     4	 * Decides which days to fetch for one hub, so each run is incremental:
88	     5	 * - nothing stored yet → everything from the history start to yesterday;
89	     6	 * - otherwise → any missing days, plus the last N days again (the archive
90	     7	 *   revises its newest values).
91	     8	 */
92	     9	import { addDays, daysInclusive, minDate } from "../utils/dates";
93	    10	
94	    11	/** Inputs for {@link planWeatherRange}. */
95	    12	export interface PlanInput {
96	    13	  /** Newest date already stored for the hub, or null if none. */
97	    14	  latestStoredDate: string | null;
98	    15	  /** Today's date (UTC) `YYYY-MM-DD`. We fetch up to yesterday. */
99	    16	  today: string;
100	    17	  /** First day of history we keep. */
101	    18	  historyStart: string;
102	    19	  /** How many recent days to re-fetch every run. */
103	    20	  refetchRecentDays: number;
104	    21	}
105	    22	
106	    23	/** A date range to fetch, both ends included. */
107	    24	export interface DateRange {
108	    25	  startDate: string;
109	    26	  endDate: string;
110	    27	}
111	    28	
112	    29	/**
113	    30	 * Plans the date range to fetch for one hub.
114	    31	 * @param input - what's stored, today's date and the policy settings.
115	    32	 * @returns the range to fetch, or null when there is nothing to do.
116	    33	 */
117	    34	export function planWeatherRange(input: PlanInput): DateRange | null {
118	    35	  const endDate = addDays(input.today, -1);
119	    36	  if (daysInclusive(input.historyStart, endDate) === 0) return null;
120	    37	
121	    38	  if (input.latestStoredDate === null) return { startDate: input.historyStart, endDate };
122	    39	
123	    40	  const firstMissing = addDays(input.latestStoredDate, 1);
124	    41	  const refetchFrom = addDays(endDate, -(input.refetchRecentDays - 1));
125	    42	  const startDate = [firstMissing, refetchFrom].reduce(minDate);
126	    43	  const clampedStart = daysInclusive(input.historyStart, startDate) === 0 ? input.historyStart : startDate;
127	    44	  return daysInclusive(clampedStart, endDate) === 0 ? null : { startDate: clampedStart, endDate };
128	    45	}
