189	     1	/**
190	     2	 * @module core/ingest/rateLimiter
191	     3	 *
192	     4	 * Keeps Open-Meteo requests under its per-minute, per-hour and per-day limits.
193	     5	 * Each request has a *weight* (long date ranges count as several calls), so
194	     6	 * this is a sliding-window limiter over weighted calls.
195	     7	 *
196	     8	 * Note: history lives in memory, so it protects one process run. That's enough
197	     9	 * because the full load is a single run and the nightly run is tiny.
198	    10	 */
199	    11	import { sleep as defaultSleep, type SleepFn } from "../data/http";
200	    12	
201	    13	/** Max weighted calls per window. */
202	    14	export interface RateLimits {
203	    15	  perMinute: number;
204	    16	  perHour: number;
205	    17	  perDay: number;
206	    18	}
207	    19	
208	    20	/** One past request: when it was made and how much it weighed. */
209	    21	export interface CallRecord {
210	    22	  at: number;
211	    23	  weight: number;
212	    24	}
213	    25	
214	    26	const MINUTE = 60_000;
215	    27	const HOUR = 60 * MINUTE;
216	    28	const DAY = 24 * HOUR;
217	    29	
218	    30	/**
219	    31	 * How long to wait before a request of `weight` can go out without breaking any limit.
220	    32	 * Pure function: no clock, no side effects.
221	    33	 * @param history - previous calls (any order).
222	    34	 * @param now - current time in ms.
223	    35	 * @param weight - weight of the request we want to make.
224	    36	 * @param limits - window limits.
225	    37	 * @returns milliseconds to wait (0 = go now).
226	    38	 * @throws Error when a single request is heavier than a whole window allows.
227	    39	 */
228	    40	export function computeWaitMs(history: CallRecord[], now: number, weight: number, limits: RateLimits): number {
229	    41	  const windows: [number, number][] = [
230	    42	    [MINUTE, limits.perMinute],
231	    43	    [HOUR, limits.perHour],
232	    44	    [DAY, limits.perDay],
233	    45	  ];
234	    46	  let wait = 0;
235	    47	  for (const [length, limit] of windows) {
236	    48	    if (weight > limit) throw new Error(`Request weight ${weight} exceeds the ${length / MINUTE}-minute limit ${limit}`);
237	    49	    // Oldest first: drop calls until the remaining ones leave room for this request.
238	    50	    const inWindow = history.filter((call) => call.at > now - length).sort((a, b) => a.at - b.at);
239	    51	    let used = inWindow.reduce((sum, call) => sum + call.weight, 0);
240	    52	    for (const call of inWindow) {
241	    53	      if (used + weight <= limit) break;
242	    54	      used -= call.weight;
243	    55	      wait = Math.max(wait, call.at + length - now);
244	    56	    }
245	    57	  }
246	    58	  return wait;
247	    59	}
248	    60	
249	    61	/** Stateful limiter used by the ingest run. */
250	    62	export class WeightedRateLimiter {
251	    63	  private readonly history: CallRecord[] = [];
252	    64	
253	    65	  /**
254	    66	   * @param limits - window limits.
255	    67	   * @param clock - returns the current time (injectable for tests).
256	    68	   * @param sleepImpl - waits (injectable for tests).
257	    69	   * @param onWait - called before each wait, e.g. to print progress.
258	    70	   */
259	    71	  constructor(
260	    72	    private readonly limits: RateLimits,
261	    73	    private readonly clock: () => number = Date.now,
262	    74	    private readonly sleepImpl: SleepFn = defaultSleep,
263	    75	    private readonly onWait: (ms: number) => void = () => {},
264	    76	  ) {}
265	    77	
266	    78	  /**
267	    79	   * Waits until a request of `weight` is allowed, then records it.
268	    80	   * @param weight - weighted call count of the upcoming request.
269	    81	   * @returns the milliseconds waited.
270	    82	   */
271	    83	  async acquire(weight: number): Promise<number> {
272	    84	    const wait = computeWaitMs(this.history, this.clock(), weight, this.limits);
273	    85	    if (wait > 0) {
274	    86	      this.onWait(wait);
275	    87	      await this.sleepImpl(wait);
276	    88	    }
277	    89	    this.history.push({ at: this.clock(), weight });
278	    90	    return wait;
279	    91	  }
280	    92	}
