582	    15	export function percentile(values: readonly number[], p: number): number {
583	    16	  if (values.length === 0) throw new Error("percentile of an empty list");
584	    17	  if (p < 0 || p > 1) throw new Error(`percentile p must be within 0..1, got ${p}`);
585	    18	  const sorted = [...values].sort((a, b) => a - b);
586	    19	  const index = (sorted.length - 1) * p;
587	    20	  const lower = Math.floor(index);
