 92	/** Per-request data and settings for the agent. */
 93	export interface AgentContext {
 94	  hubs: Hub[];
 95	  hubById: Map<string, Hub>;
 96	  snapshotByHub: Map<string, StoredSnapshot>;
 97	  levelsByHub: Map<string, HubLevels>;
 98	  weatherBounds: DataBounds;
 99	  /** Today's date `YYYY-MM-DD` (UTC). "Last year" is derived from it (G11). */
100	  today: string;
101	  units: UnitSystem;
102	  getWeatherDays: (hubId: string, startDate: string, endDate: string) => Promise<DailyWeather[]>;
103	}
104	
105	/** Where the context comes from (injectable for tests). */
106	export interface AgentContextDeps {
107	  listActiveHubs: () => Promise<Hub[]>;
108	  getLatestSnapshots: () => Promise<StoredSnapshot[] | null>;
109	  getWeatherBounds: () => Promise<DataBounds | null>;
110	  getWeatherDays: AgentContext["getWeatherDays"];
111	}
