113	/**
114	 * Real levels per hub: overall, and each hazard's score mapped with the same cut-offs.
115	 * @param snapshot - a hub's latest snapshot.
116	 * @returns the levels.
117	 */
118	export function levelsOf(snapshot: StoredSnapshot): HubLevels {
119	  return {
120	    overall: snapshot.riskLevel,
121	    hazards: Object.fromEntries(HAZARDS.map((h) => [h, riskLevelFor(snapshot.hazards[h].score)])) as Record<Hazard, RiskLevel>,
122	  };
123	}
124	
125	/**
126	 * Loads the context for one turn.
127	 * @param deps - data sources.
128	 * @param options - today's date and the user's unit system.
129	 * @returns the context.
130	 * @throws BoundaryError (database) when nothing has been scored or ingested yet.
131	 */
132	export async function loadAgentContext(
133	  deps: AgentContextDeps,
134	  options: { today: string; units: UnitSystem },
135	): Promise<AgentContext> {
136	  const [hubs, snapshots, weatherBounds] = await Promise.all([
137	    deps.listActiveHubs(),
138	    deps.getLatestSnapshots(),
139	    deps.getWeatherBounds(),
140	  ]);
141	  if (!snapshots || !weatherBounds) {
142	    throw new BoundaryError({
143	      name: "NoDataError",
144	      message: "No scores or weather data yet — run `npm run ingest` first",
145	      functionName: "loadAgentContext",
146	      boundary: "database",
147	    });
148	  }
149	  const active = new Set(hubs.map((h) => h.id));
150	  const scored = snapshots.filter((s) => active.has(s.hubId));
151	  return {
152	    hubs,
153	    hubById: new Map(hubs.map((h) => [h.id, h])),
154	    snapshotByHub: new Map(scored.map((s) => [s.hubId, s])),
155	    levelsByHub: new Map(scored.map((s) => [s.hubId, levelsOf(s)])),
156	    weatherBounds,
157	    today: options.today,
158	    units: options.units,
159	    getWeatherDays: deps.getWeatherDays,
160	  };
161	}
