116	/**
117	 * Classifies any thrown value into a friendly user error.
118	 * @param error - whatever was thrown.
119	 * @returns the user error (never contains internal details).
120	 */
121	export function toUserError(error: unknown): UserError {
122	  if (error instanceof AgentInputError) return userError("invalid_request", error.message);
123	  if (error instanceof ZodError) return userError("invalid_request");
124	  if (error instanceof BoundaryError) {
125	    if (error.name === "NoDataError") return userError("no_data");
126	    if (error.boundary === "llm") return userError("agent_failed");
