141	   141	 * hazard days in it. Percentages are of days WITH data, and coverage is
142	   142	 * reported so the agent can be honest about gaps.
143	   143	 */
144	   144	import type { DailyWeather } from "../domain/weather";
145	   145	import { countMetricDays, type DateWindow } from "../scoring/observedSignals";
