149	   149	/** A period as the tool receives it. `month` (1–12) narrows a year. */
150	   150	export type PeriodRequest =
151	   151	  | { kind: "year"; year: number; month?: number }
152	   152	  | { kind: "range"; startDate: string; endDate: string }
