155	   155	/** A resolved period: exact dates, a human label, and notes about clipping. */
156	   156	export interface ResolvedPeriod extends DateWindow {
157	   157	  label: string;
158	   158	  notes: string[];
159	   159	}
160	   160	
161	   161	/** The range of dates we have data for. */
162	   162	export interface DataBounds {
163	   163	  earliest: string;
164	   164	  latest: string;
165	   165	}
166	   166	
167	   167	const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
168	   168	
169	   169	/** @returns the last day of a month, `YYYY-MM-DD`. */
170	   170	function lastDayOfMonth(year: number, month: number): string {
171	   171	  return addDays(`${month === 12 ? year + 1 : year}-${String(month === 12 ? 1 : month + 1).padStart(2, "0")}-01`, -1);
172	   172	}
