174	   174	/**
175	   175	 * Resolves a requested period to exact dates within the available data.
176	   176	 * @param request - year (optionally a month), date range, or last 12 months.
177	   177	 * @param bounds - earliest and latest stored day.
178	   178	 * @returns the dates, a label and notes (e.g. "2026 is incomplete").
179	   179	 * @throws Error with a user-readable message when the period has no data or is malformed.
180	   180	 */
181	   181	export function resolvePeriod(request: PeriodRequest, bounds: DataBounds): ResolvedPeriod {
182	   182	  let start: string;
183	   183	  let end: string;
184	   184	  let label: string;
185	   185	
186	   186	  if (request.kind === "last12Months") {
187	   187	    end = bounds.latest;
188	   188	    start = addDays(end, -364);
189	   189	    label = `the last 12 months (${start} to ${end})`;
190	   190	  } else if (request.kind === "year") {
191	   191	    const { year, month } = request;
192	   192	    if (month !== undefined && (month < 1 || month > 12)) throw new Error(`Month must be 1–12, got ${month}.`);
193	   193	    start = month ? `${year}-${String(month).padStart(2, "0")}-01` : `${year}-01-01`;
194	   194	    end = month ? lastDayOfMonth(year, month) : `${year}-12-31`;
195	   195	    label = month ? `${MONTHS[month - 1]} ${year}` : `calendar year ${year}`;
196	   196	  } else {
197	   197	    start = request.startDate;
198	   198	    end = request.endDate;
199	   199	    if (daysInclusive(start, end) === 0) throw new Error(`The end date ${end} is before the start date ${start}.`);
200	   200	    label = `${start} to ${end}`;
201	   201	  }
202	   202	
203	   203	  if (end < bounds.earliest || start > bounds.latest) {
204	   204	    throw new Error(`No weather data for ${label}: our data starts ${bounds.earliest} and ends ${bounds.latest}.`);
205	   205	  }
206	   206	
207	   207	  const notes: string[] = [];
208	   208	  if (start < bounds.earliest) {
209	   209	    notes.push(`Our data starts ${bounds.earliest}, so the period was shortened to begin then.`);
210	   210	    start = bounds.earliest;
211	   211	  }
212	   212	  if (end > bounds.latest) {
213	   213	    notes.push(`The period is incomplete: data runs through ${bounds.latest}.`);
214	   214	    end = bounds.latest;
215	   215	  }
216	   216	  return { start, end, label, notes };
217	   217	}
