219	   219	/** Result of counting one metric over a period. */
220	   220	export interface WeatherStat {
221	   221	  daysMeeting: number;
222	   222	  daysWithData: number;
223	   223	  daysInPeriod: number;
224	   224	  /** daysMeeting ÷ daysWithData × 100, 1 decimal (null when no data). */
225	   225	  percentOfDays: number | null;
226	   226	  /** daysWithData ÷ daysInPeriod (0..1). */
227	   227	  coverage: number;
228	   228	}
