230	   230	/**
231	   231	 * Counts days meeting a metric in a period.
232	   232	 * @param days - daily rows (rows outside the period are ignored).
233	   233	 * @param metricId - which hazard-day metric.
234	   234	 * @param period - the exact dates.
235	   235	 * @returns counts, percentage and coverage.
236	   236	 */
237	   237	export function computeWeatherStat(days: DailyWeather[], metricId: DayMetricId, period: DateWindow): WeatherStat {
238	   238	  const inPeriod = days.filter((day) => day.date >= period.start && day.date <= period.end);
239	   239	  const { hits, present } = countMetricDays(inPeriod, metricId);
240	   240	  const daysInPeriod = daysInclusive(period.start, period.end);
241	   241	  return {
242	   242	    daysMeeting: hits,
243	   243	    daysWithData: present,
244	   244	    daysInPeriod,
245	   245	    percentOfDays: present === 0 ? null : Math.round((hits / present) * 1000) / 10,
246	   246	    coverage: daysInPeriod === 0 ? 0 : Math.round((present / daysInPeriod) * 1000) / 1000,
247	   247	  };
248	   248	}
