260	   260	/**
261	   261	 * Counts metric days per calendar month across a period (every month in the
262	   262	 * period is listed, even with no data), for the seasonality strip.
263	   263	 * @param days - daily rows (rows outside the period are ignored).
264	   264	 * @param metricId - which hazard-day metric.
265	   265	 * @param period - the exact dates.
266	   266	 * @returns one entry per month, oldest first.
267	   267	 */
268	   268	export function computeMonthlyCounts(days: DailyWeather[], metricId: DayMetricId, period: DateWindow): MonthlyCount[] {
269	   269	  const months: MonthlyCount[] = [];
270	   270	  let cursor = `${period.start.slice(0, 7)}-01`;
271	   271	  while (cursor <= period.end) {
272	   272	    const month = cursor.slice(0, 7);
273	   273	    const inMonth = days.filter((d) => d.date.startsWith(month) && d.date >= period.start && d.date <= period.end);
274	   274	    const { hits, present } = countMetricDays(inMonth, metricId);
275	   275	    months.push({ month, label: `${MONTHS[Number(month.slice(5)) - 1].slice(0, 3)} ${month.slice(0, 4)}`, daysMeeting: hits, daysWithData: present });
276	   276	    cursor = addDays(lastDayOfMonth(Number(month.slice(0, 4)), Number(month.slice(5))), 1);
277	   277	  }
