280	   280	/**
281	   281	 * @module core/scoring/confidence
282	   282	 *
283	   283	 * Rule-based confidence (D51), computed in code — never by the LLM.
284	   284	 * Trust depends on whether data is complete and whether sources AGREE,
285	   285	 * not on how many sources there are.
286	   286	 */
287	   287	import { CONFIDENCE_RULES } from "./config";
288	   288	import { CONFIDENCE_LEVELS, type Confidence } from "./types";
289	   289	
290	   290	/** A confidence level plus a plain-language reason the agent can quote. */
291	   291	export interface ConfidenceResult {
292	   292	  confidence: Confidence;
293	   293	  reason: string;
294	   294	}
295	   295	
296	   296	/**
297	   297	 * Confidence from data coverage alone: a weather stat's, and the coverage part of a hazard's.
298	   298	 * @param coverage - share of days with weather data (0..1).
299	   299	 * @param span - what the days belong to, for the reason ("window", "period").
300	   300	 * @returns level and reason.
301	   301	 */
302	   302	export function coverageConfidence(coverage: number, span = "period"): ConfidenceResult {
303	   303	  const percentMissing = Math.round((1 - coverage) * 100);
304	   304	  if (coverage < CONFIDENCE_RULES.minimumCoverage) return { confidence: "low", reason: `${percentMissing}% of days in the ${span} have no weather data.` };
305	   305	  if (coverage < CONFIDENCE_RULES.completeCoverage) return { confidence: "medium", reason: `${percentMissing}% of days in the ${span} have no weather data.` };
306	   306	  return { confidence: "high", reason: `Every day in the ${span} has weather data.` };
307	   307	}
308	   308	
309	   309	/**
310	   310	 * Confidence for a hazard scored from observed weather AND FEMA.
311	   311	 *
312	   312	 * The "sources disagree" check compares LIKE WITH LIKE (D56): `comparableFemaScore`
313	   313	 * is the FEMA score built only from signals observed weather can also see
314	   314	 * (e.g. winter without ice storms). Pass `"not-comparable"` when the halves
315	   315	 * measure different things (flood: heavy rain ≠ flood warnings) to skip the check.
316	   316	 * @param input - the two halves (null = missing), the comparable FEMA score, and observed coverage (0..1).
317	   317	 * @returns level and reason.
318	   318	 */
319	   319	export function hybridConfidence(input: {
320	   320	  observedScore: number | null;
321	   321	  femaScore: number | null;
322	   322	  /** FEMA score for the cross-check; defaults to `femaScore`. */
323	   323	  comparableFemaScore?: number | null | "not-comparable";
324	   324	  coverage: number;
325	   325	}): ConfidenceResult {
326	   326	  const { observedScore, femaScore, coverage } = input;
327	   327	  const comparable = input.comparableFemaScore === undefined ? femaScore : input.comparableFemaScore;
328	   328	
329	   329	  if (observedScore === null || femaScore === null) {
330	   330	    const missing = observedScore === null ? "observed weather" : "FEMA";
331	   331	    return { confidence: "low", reason: `Only one of two sources is available (${missing} data is missing).` };
332	   332	  }
333	   333	  if (coverage < CONFIDENCE_RULES.completeCoverage) return coverageConfidence(coverage, "window");
334	   334	  if (comparable === "not-comparable") {
335	   335	    return {
336	   336	      confidence: "high",
337	   337	      reason:
338	   338	        "Complete data. The two sources measure different things (heavy-rain days vs. county-wide flood warnings), so they are combined but not cross-checked.",
339	   339	    };
340	   340	  }
341	   341	  if (comparable !== null) {
342	   342	    const gap = Math.abs(observedScore - comparable);
343	   343	    if (gap > CONFIDENCE_RULES.disagreementPoints) {
344	   344	      return {
345	   345	        confidence: "medium",
346	   346	        reason: `The two sources disagree: observed weather scores ${Math.round(observedScore)}, FEMA's long-term county record scores ${Math.round(comparable)} on the same phenomenon.`,
347	   347	      };
348	   348	    }
349	   349	  }
350	   350	  return { confidence: "high", reason: "Complete data, and observed weather and FEMA's record tell the same story." };
351	   351	}
352	   352	
353	   353	/**
354	   354	 * Confidence for a hazard scored from FEMA only (hurricane, severe storms):
355	   355	 * FEMA's long historical record is the right source for rare events.
356	   356	 * @param femaScore - the FEMA score, or null when the record is missing.
357	   357	 * @returns level and reason.
358	   358	 */
359	   359	export function femaOnlyConfidence(femaScore: number | null): ConfidenceResult {
360	   360	  if (femaScore === null) return { confidence: "low", reason: "No FEMA record is available for this hub's county." };
361	   361	  return { confidence: "high", reason: "Based on FEMA's long-term county frequency record (rare events need decades of data)." };
362	   362	}
363	   363	
364	   364	/**
365	   365	 * The weakest of several confidence levels.
366	   366	 * @param levels - at least one level.
367	   367	 * @returns the lowest one.
368	   368	 * @throws Error on an empty list.
369	   369	 */
370	   370	export function weakestConfidence(levels: Confidence[]): Confidence {
371	   371	  if (levels.length === 0) throw new Error("weakestConfidence needs at least one level");
372	   372	  return levels.reduce((weakest, level) =>
373	   373	    CONFIDENCE_LEVELS.indexOf(level) > CONFIDENCE_LEVELS.indexOf(weakest) ? level : weakest,
374	   374	  );
375	   375	}
