    const fetchImpl = vi
      .fn<FetchLike>()
      .mockResolvedValueOnce(new Response("slow down", { status: 429, headers: { "retry-after": "3600" } }))
      .mockResolvedValueOnce(respond(200, { ok: 4 }));
